def compute(vars):
    amortized_cost_available_for_sale = vars["v1"]
    total_amortized_cost_securities = vars["v2"]

    if total_amortized_cost_securities == 0:
        return None

    percentage = (
        amortized_cost_available_for_sale / total_amortized_cost_securities
    ) * 100

    return {
        "value": percentage,
        "trace": {
            "amortized_cost_available_for_sale": amortized_cost_available_for_sale,
            "total_amortized_cost_securities": total_amortized_cost_securities,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
